script:
frappe.ui.form.on('Item', {
    refresh(frm) {
        // Refresh custom values
        update_multiplication_factor(frm);
        calculate_estimated_weight(frm);
    },
    custom_length_mm: function(frm) {
        calculate_estimated_weight(frm);
    },
    custom_width_mm: function(frm) {
        calculate_estimated_weight(frm);
    },
    custom_thickness_mm: function(frm) {
        calculate_estimated_weight(frm);
    },
    item_group: function(frm) {
        update_multiplication_factor(frm);
        calculate_estimated_weight(frm);
    }
});

function update_multiplication_factor(frm) {
    if (frm.doc.item_group) {
        frappe.db.get_value('Item Group', frm.doc.item_group, 'custom_multiplication_factor')
            .then(r => {
                let multiplication_factor = r.message.custom_multiplication_factor || 0;
                frm.set_value('custom_multiplication_factor', multiplication_factor);
            })
            .catch(err => {
                console.error('Error fetching multiplication factor:', err);
            });
    }
}

function calculate_estimated_weight(frm) {
    let length = frm.doc.custom_length_mm || 0;
    let width = frm.doc.custom_width_mm || 0;
    let thickness = frm.doc.custom_thickness_mm || 0;
    
    if (length && width && thickness && frm.doc.item_group) {
        // Fetch both multiplication factor and formula from Item Group
        frappe.db.get_value('Item Group', frm.doc.item_group, ['custom_multiplication_factor', 'custom_formula'])
            .then(r => {
                console.log('Fetched Item Group data:', r);
                let multiplication_factor = r.message.custom_multiplication_factor || 0;
                let formula = r.message.custom_formula || '';
                
                console.log('Multiplication factor:', multiplication_factor);
                console.log('Formula:', formula);
                
                let estimated_weight = 0;
                
                // Apply formula based on Item Group setting
                switch(formula) {
                    case '(L * W * T * MF) / 100000':
                        if (length && width && thickness && multiplication_factor) {
                            estimated_weight = (length * width * thickness * multiplication_factor) / 100000;
                        }
                        break;
                    
                    case '(L * W * MF) / 10000':
                        if (length && width && multiplication_factor) {
                            estimated_weight = (length * width * multiplication_factor) / 10000;
                        }
                        break;
                    
                    case '(L * T * MF) / 10000':
                        if (length && thickness && multiplication_factor) {
                            estimated_weight = (length * thickness * multiplication_factor) / 10000;
                        }
                        break;
                    
                    case '(W * T * MF) / 10000':
                        if (width && thickness && multiplication_factor) {
                            estimated_weight = (width * thickness * multiplication_factor) / 10000;
                        }
                        break;
                    
                    default:
                        // Default formula if none specified
                        if (length && width && thickness && multiplication_factor) {
                            estimated_weight = (length * width * thickness * multiplication_factor) / 100000;
                        }
                }
                
                console.log('Calculated estimated weight:', estimated_weight);
                frm.set_value('custom_estimated_weight', estimated_weight);
            })
            .catch(err => {
                console.error('Error fetching Item Group data:', err);
            });
    } else {
        frm.set_value('custom_estimated_weight', 0);
    }
}
